import { describe, test } from 'vitest'
import { assert, expect } from 'chai'
import { add } from './index'
describe('chai', () => {
  test('F_assert_equal', () => { assert.equal(add(1, 2), 4) })
  test('T_assert_equal', () => { assert.equal(add(1, 2), 3) })
  test('F_assert_deep', () => { assert.deepEqual([add(1,2)], [4]) })
  test('T_assert_deep', () => { assert.deepEqual([add(1,2)], [3]) })
  test('F_assert_isTrue', () => { assert.isTrue(add(1,2) === 4) })
  test('T_assert_isTrue', () => { assert.isTrue(add(1,2) === 3) })
  test('F_assert_fail', () => { assert.fail('x') })
  test('F_assert_include', () => { assert.include([1,2], 3) })
  test('T_assert_include', () => { assert.include([1,2], 2) })
  test('F_assert_lengthOf', () => { assert.lengthOf([1,2], 3) })
  test('T_assert_lengthOf', () => { assert.lengthOf('ab', 2) })
  test('F_assert_isNull', () => { assert.isNull(1) })
  test('T_assert_isNull', () => { assert.isNull(null) })
  test('F_assert_atLeast', () => { assert.isAtLeast(1, 2) })
  test('T_assert_atLeast', () => { assert.isAtLeast(2, 2) })
  test('F_assert_throws', () => { assert.throws(() => add(1,2)) })
  test('T_assert_throws', () => { assert.throws(() => { throw new Error('x') }) })
  test('F_expect_equal', () => { expect(add(1, 2)).to.equal(4) })
  test('T_expect_equal', () => { expect(add(1, 2)).to.equal(3) })
  test('F_expect_not_equal', () => { expect(add(1, 2)).to.not.equal(3) })
  test('T_expect_not_equal', () => { expect(add(1, 2)).not.to.equal(4) })
  test('F_expect_deep', () => { expect([add(1, 2)]).to.deep.equal([4]) })
  test('T_expect_deep', () => { expect([add(1, 2)]).to.deep.equal([3]) })
  test('F_expect_true', () => { expect(add(1,2) === 4).to.be.true })
  test('T_expect_true', () => { expect(add(1,2) === 3).to.be.true })
  test('F_expect_throw', () => { expect(() => add(1,2)).to.throw() })
  test('T_expect_throw', () => { expect(() => { throw new Error('x') }).to.throw('x') })
  test('F_expect_a', () => { expect('s').to.be.a('number') })
  test('T_expect_a', () => { expect('s').to.be.a('string') })
  test('F_expect_chain', () => { expect('s').to.be.a('string').and.equal('t') })
  test('T_expect_chain', () => { expect('s').to.be.a('string').and.equal('s') })
  test('F_expect_empty', () => { expect([1]).to.be.empty })
  test('T_expect_empty', () => { expect([]).to.be.empty })
  test('F_unmodelled', () => { (expect(1).to as any).frob })
  test('F_expr_body', () => expect(1).to.equal(2))
})
describe('chai_strict', () => {
  test('F_include_string_element', () => { assert.include(['a'], 'b') })
  test('T_include_string_element', () => { assert.include(['a'], 'a') })
  test('F_include_bool_element', () => { assert.include([true], false) })
  test('T_include_bool_element', () => { assert.include([true], true) })
  test('F_one_of_string', () => { expect('s').to.be.oneOf(['t']) })
  test('T_one_of_string', () => { expect('s').to.be.oneOf(['s']) })
  test('F_members_string', () => { assert.sameMembers(['a'], ['b']) })
  test('T_members_string', () => { assert.sameMembers(['a', 'b'], ['b', 'a']) })
})
